const virtual_device = require('./index')

module.exports = run_scenarios

// runs the three device checks
async function run_scenarios (opts = {}) {
  const document = opts.document || globalThis.document
  const mount = opts.mount || document?.body
  const devices = virtual_device({ document })
  const results = []
  const on_result = opts.on_result
  const device_a = devices.create(device_runtime, { id: 'device-a' })
  const device_b = devices.create(device_runtime, { id: 'device-b' })
  const device_c = devices.create(device_runtime, { id: 'device-c' })
  mount.append(device_a.view, device_b.view, device_c.view)
  try {
    await Promise.all([device_a.ready, device_b.ready, device_c.ready])
    check({ results, on_result, name: 'create three devices', passed: devices.list().length === 3 })

    const pong = await device_a.port.request('ping', 'hello')
    check({ results, on_result, name: 'host to child rpc', passed: pong === 'hello' })

    device_a.port.handle('host_ping', host_ping)
    const host_pong = await device_a.port.request('ask_host', 'hello')
    check({ results, on_result, name: 'child to host rpc', passed: host_pong === 'host:hello' })

    await device_a.port.request('increase')
    await device_a.port.request('increase')
    await device_b.port.request('increase')
    const device_a_status = await device_a.port.request('status')
    const device_b_status = await device_b.port.request('status')
    check({ results, on_result, name: 'isolated runtime state', passed: device_a_status.count === 2 && device_b_status.count === 1 })

    devices.connect(device_a.id, device_b.id)
    devices.connect(device_b.id, device_c.id)
    await device_a.port.request('send', { to: device_b.id, data: 'device-a-to-b' })
    await device_b.port.request('send', { to: device_c.id, data: 'device-b-to-c' })
    const linked_device_b = await device_b.port.request('status')
    const linked_device_c = await device_c.port.request('status')
    const device_b_received = linked_device_b.messages.some(has_message('device-a', 'device-a-to-b'))
    const device_c_received = linked_device_c.messages.some(has_message('device-b', 'device-b-to-c'))
    check({ results, on_result, name: 'linked device routing', passed: device_b_received && device_c_received })

    devices.disconnect(device_a.id, device_b.id)
    await device_a.port.request('send', { to: device_b.id, data: 'blocked' })
    const disconnected = await device_a.port.request('status')
    const blocked = disconnected.errors.some(has_error(device_b.id))
    check({ results, on_result, name: 'disconnected route rejected', passed: blocked })

    const pending = device_b.port.request('wait')
    devices.close(device_b.id)
    const close_error = await pending.then(no_error, get_error)
    check({ results, on_result, name: 'close rejects pending rpc', passed: close_error === 'Port is closed' })
    check({ results, on_result, name: 'close removes device', passed: !devices.get(device_b.id) && devices.list().length === 2 })
    return results
  } finally {
    devices.close_all()
  }
}

/***************************************
DEVICE RUNTIME
***************************************/
// same small api for every device
function device_runtime (port) {
  const state = { count: 0, messages: [], errors: [] }
  port.handle('ping', ping)
  port.handle('ask_host', ask_host)
  port.handle('increase', increase)
  port.handle('send', send)
  port.handle('status', status)
  port.handle('wait', wait)
  port.addEventListener('message', receive)

  function ping (value) { return value }

  function ask_host (value) { return port.request('host_ping', value) }

  function increase () { return ++state.count }

  function send (message) {
    port.postMessage({ type: 'virtual-send', to: message.to, data: message.data })
  }

  function status () {
    return {
      count: state.count,
      messages: state.messages.slice(),
      errors: state.errors.slice()
    }
  }

  function wait () { return new Promise(wait_forever) }

  // stays pending so we can test cleanup
  function wait_forever () {}

  function receive (event) {
    const message = event.data || {}
    if (message.type === 'virtual-message') state.messages.push({ from: message.from, data: message.data })
    if (message.type === 'virtual-error') state.errors.push({ to: message.to, error: message.error })
  }
}

/***************************************
SCENARIO HELPERS
***************************************/
function host_ping (value) { return `host:${value}` }

function has_message (from, data) {
  return function matches_message (message) { return message.from === from && message.data === data }
}

function has_error (to) {
  return function matches_error (message) { return message.to === to }
}

function no_error () { return null }

function get_error (error) { return error.message }

function check ({ results, on_result, name, passed }) {
  if (!passed) throw new Error(`Scenario failed: ${name}`)
  const result = { name, passed }
  results.push(result)
  on_result?.(result)
}
